// Join checked-in CSS without changing cascade order or relative URL directories.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const bundles = {
  'static/css/frontend.css': ['static/css/fonts.css', 'static/css/style.min.css', 'static/css/layout.css'],
  'static/libs/slick/cooklook-slick.css': ['static/libs/slick/slick.min.css', 'static/libs/slick/slick-theme.min.css']
};
function build(check = false) {
  for (const [output, inputs] of Object.entries(bundles)) {
    const css = '/* Generated by tools/build-frontend-css.cjs; edit the source CSS. */\n' + inputs.map(file =>
      fs.readFileSync(path.join(root, file), 'utf8').replace(/\/\*# sourceMappingURL=[\s\S]*?\*\//g, '').trim()
    ).join('\n') + '\n';
    const destination = path.join(root, output);
    if (check) {
      if (!fs.existsSync(destination) || fs.readFileSync(destination, 'utf8') !== css) throw new Error('Rebuild stale CSS: ' + output);
    } else fs.writeFileSync(destination, css);
  }
}
module.exports = build;
if (require.main === module) build(process.argv.includes('--check'));
